const apps = [
  { app: 'circle', url: 'https://circle.fractionl.ai/agent.json' },
  { app: 'pulse', url: 'https://pulse.fractionl.ai/product-truth.json' },
  { app: 'ctrl', url: 'https://ctrl.themindmaker.ai/.well-known/product.json' }
  // TODO: gutted, merciless, onalert retired from the OS control plane 2026-07-06 (Krish directive). Removed from this health check. Apps stay deployed until Krish sunsets them manually; do not re-add.
  // TODO: plinth (https://plinth-tan.vercel.app) and full-time (https://full-time-alpha.vercel.app) are the replacement products but neither exposes a product-truth endpoint yet. Add them here once each ships one; do not invent a URL in the meantime.
];
const failures = [];
const summary = [];
for (const a of apps) {
  let status = 0, ok = false;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: a.url, returnFullResponse: true, timeout: 15000, ignoreHttpStatusErrors: true });
    status = res.statusCode;
    ok = status >= 200 && status < 300;
  } catch (e) { status = -1; ok = false; }
  summary.push({ app: a.app, status, ok });
  if (!ok) failures.push(a.app + ' (' + status + ')');
}
if (failures.length === 0) return [];
const list = failures.join(', ');
return [{ json: { alert: true, failures, summary, checked_at: new Date().toISOString(), text: 'Fleet attribution health alert: ' + failures.length + ' product-truth surface(s) DOWN - ' + list + '. The fleet sells from these; check the app and its emit wiring (MINDMAKER_OS_ARCHITECTURE 11.4).' } }];
